class ExclusiveThreadingHTTPServer(ThreadingHTTPServer):
    """HTTP server with single-owner bind semantics on Windows."""

    allow_reuse_address = False

    def server_bind(self) -> None:
        # On Windows SO_REUSEADDR permits multiple unrelated processes to bind
        # the same listening address.  SO_EXCLUSIVEADDRUSE must be set before
        # bind(), so doing this after ThreadingHTTPServer.__init__ is too late.
        if os.name == "nt":
            exclusive = getattr(socket, "SO_EXCLUSIVEADDRUSE", 12)
            self.socket.setsockopt(socket.SOL_SOCKET, exclusive, 1)
        super().server_bind()


class Handler(BaseHTTPRequestHandler):
    root: Path
    windows_root: Path
    sessions_root: Path

    def send_bytes(self, code: int, content_type: str, body: bytes) -> None:
        self.send_response(code)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:  # noqa: N802
        if self.path == "/api/status":
            now = time.time()
            with _snapshot_lock:
                if (now - float(_snapshot_cache.get("checked_at", 0) or 0) >= _SNAPSHOT_CACHE_TTL
                        or _snapshot_cache.get("value") is None):
                    _snapshot_cache["value"] = snapshot(self.root, self.windows_root, self.sessions_root)
                    _snapshot_cache["checked_at"] = time.time()
                data = _snapshot_cache["value"]
            body = json.dumps(data, ensure_ascii=False).encode("utf-8")
            self.send_bytes(200, "application/json; charset=utf-8", body)
        elif self.path == "/healthz":
            self.send_bytes(200, "application/json", b'{"status":"ok"}')
        elif self.path in {"/", "/index.html"}:
            self.send_bytes(200, "text/html; charset=utf-8", PAGE.encode("utf-8"))
        else:
            self.send_bytes(404, "text/plain; charset=utf-8", "not found".encode())

    def log_message(self, _format: str, *_args: Any) -> None:
        return


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", type=Path,
                        default=Path(os.environ.get("CODEX_LOOP_MONITOR_ROOT", str(DEFAULT_ROOT))))
    parser.add_argument("--port", type=int, default=8765)
    parser.add_argument("--windows-root", type=Path, default=DEFAULT_WINDOWS_ROOT)
    parser.add_argument("--sessions-root", type=Path, default=DEFAULT_SESSIONS_ROOT)
    args = parser.parse_args()
    Handler.root = args.root
    Handler.windows_root = args.windows_root
    Handler.sessions_root = args.sessions_root
    try:
        server = ExclusiveThreadingHTTPServer(("127.0.0.1", args.port), Handler)
    except OSError as exc:
        print(f"[loop_monitor_server] bind failed on port {args.port}: {exc}", file=sys.stderr)
        return 1
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

# Set-Codex-LOOP-Mode.ps1 - Activate / Deactivate / Restore / Status LOOP global mode
# Usage: .\launchers\Set-Codex-LOOP-Mode.ps1 -Mode Activate [-LoopRoot <path>] [-CodexHome <path>]
#
# Parameters:
#   -Mode        Required. One of: Activate, Deactivate, Status, Restore
#   -LoopRoot    Optional. Path to the codex-loop-open-source root directory.
#                Defaults to parent of this script directory (launchers parent).
#   -CodexHome   Optional. Override Codex home directory. Default: $USERPROFILE\.codex

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Activate', 'Deactivate', 'Status', 'Restore')]
    [string]$Mode,

    [string]$LoopRoot = '',
    [string]$CodexHome = ''
)

$ErrorActionPreference = 'Stop'

if (-not $LoopRoot) {
    $LoopRoot = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
}
$LoopRoot = [IO.Path]::GetFullPath($LoopRoot)

if (-not $CodexHome) {
    $CodexHome = Join-Path $env:USERPROFILE '.codex'
}

$tool = Join-Path $LoopRoot 'harness\global_desktop_mode.py'

if (-not (Test-Path -LiteralPath $tool -PathType Leaf)) {
    throw "global_desktop_mode.py not found at: $tool`nSet -LoopRoot to the codex-loop-open-source directory."
}

$venvPython = Join-Path $LoopRoot 'venv\Scripts\python.exe'
if (Test-Path -LiteralPath $venvPython -PathType Leaf) {
    $python = $venvPython; $pythonArgs = @()
} elseif (Get-Command py.exe -ErrorAction SilentlyContinue) {
    $python = (Get-Command py.exe).Source; $pythonArgs = @('-3')
} elseif (Get-Command python3 -ErrorAction SilentlyContinue) {
    $python = (Get-Command python3).Source; $pythonArgs = @()
} elseif (Get-Command python -ErrorAction SilentlyContinue) {
    $python = (Get-Command python).Source; $pythonArgs = @()
} else {
    throw 'Python 3.11+ is required but not found. Install from https://python.org'
}

$action = switch ($Mode) {
    'Activate'   { 'activate' }
    'Deactivate' { 'deactivate' }
    'Restore'    { 'restore' }
    default      { 'status' }
}

& $python @pythonArgs $tool $action --root $LoopRoot --codex-home $CodexHome
if ($LASTEXITCODE -ne 0) {
    throw "Codex LOOP global mode action failed (exit $LASTEXITCODE): $Mode"
}

switch ($Mode) {
    'Activate' {
        Write-Host 'LOOP mode active. Managed hooks, context payload, active agreement, and spawn gate are installed.'
        Write-Host 'Every newly started or resumed Desktop task inherits LOOP orchestration regardless of project directory.'
        Write-Host 'Restart Codex Desktop for the runtime canary to take effect.'
    }
    'Deactivate' {
        Write-Host 'LOOP mode is inactive. New or resumed Desktop tasks will not inherit LOOP orchestration.'
    }
    'Restore' {
        Write-Host 'Pre-install global AGENTS.md and hooks.json were restored from the verified backup.'
    }
}

#!/usr/bin/env python3
"""Install, activate, deactivate, and roll back Desktop-wide LOOP mode."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import subprocess
import sys
import tempfile
import tomllib
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


MODE_SCHEMA = "codex-loop-global-mode/v1"
INSTALL_SCHEMA = "codex-loop-global-mode-install/v1"
MANAGED_SCRIPTS = (
    "global_loop_mode.py",
    "subagent_lifecycle.py",
    "leaf_agent_spawn_gate.py",
    "root_agent_spawn_gate.py",
    "sol_tool_gate_router.py",
)
NEUTRAL_AGENTS = """# Codex Desktop mode boundary

LOOP behavior is selected by the machine-local Desktop mode launcher, not by
the current repository name or working directory.  When LOOP mode is active,
the global SessionStart/SubagentStart hooks provide the complete LOOP working
agreement as developer context and bind orchestration to its fixed control
root.  When that context is absent, do not infer or apply LOOP concurrency,
model-routing, packet, or harness rules merely because a previous task used
LOOP or because a repository is named after a previous LOOP installation.
"""


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=path.name + ".", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass


def json_bytes(doc: Any) -> bytes:
    return (json.dumps(doc, ensure_ascii=False, indent=2) + "\n").encode("utf-8")


def read_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except FileNotFoundError:
        return default


def state_paths(root: Path) -> tuple[Path, Path]:
    state = root.parent / "state"
    return state / "global-loop-mode.json", state / "global-loop-mode-install.json"


def active_agents(root: Path) -> bytes:
    """Return the trust-independent active-mode agreement for global AGENTS."""
    blocks = [
        "# Active Codex LOOP global mode",
        "",
        f"LOOP_CONTROL_ROOT={root}",
        "The current task workspace is the target workspace; it does not need to contain the LOOP runtime.",
        "All packets, lifecycle state, model routing, and observer state use LOOP_CONTROL_ROOT.",
        "These instructions apply to every target workspace while global LOOP mode is active.",
    ]
    for source in (root / "config" / "global_working_agreement.md", root / "AGENTS.md"):
        blocks.extend(("", f"<!-- source: {source} -->", source.read_text(encoding="utf-8-sig").strip()))
    return ("\n".join(blocks).strip() + "\n").encode("utf-8")


def managed_requirements(root: Path) -> bytes:
    data = (root / "config" / "global_requirements.toml").read_bytes()
    doc = tomllib.loads(data.decode("utf-8-sig"))
    hooks = doc.get("hooks") if isinstance(doc, dict) else None
    if not isinstance(hooks, dict) or not hooks.get("windows_managed_dir"):
        raise ValueError("managed global_requirements.toml is invalid")
    return data


def runtime_canary(root: Path, codex_home: Path, mode: dict[str, Any]) -> dict[str, Any]:
    """Find a post-activation root rollout outside the fixed control root."""
    try:
        activated = datetime.fromisoformat(
            str(mode["updated_at"]).replace("Z", "+00:00")
        ).timestamp()
    except (KeyError, TypeError, ValueError):
        return {"verified": False}
    sessions = codex_home / "sessions"
    if not sessions.exists():
        return {"verified": False}
    candidates = sorted(
        sessions.rglob("rollout-*.jsonl"),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    for path in candidates[:128]:
        try:
            if path.stat().st_mtime + 1 < activated:
                break
            with path.open(encoding="utf-8", errors="replace") as handle:
                first = json.loads(handle.readline())
                meta = first.get("payload") if first.get("type") == "session_meta" else {}
                if not isinstance(meta, dict) or meta.get("parent_thread_id"):
                    continue
                cwd = Path(str(meta.get("cwd") or "")).resolve()
                if cwd == root or root in cwd.parents:
                    continue
                handle.seek(0)
                text = handle.read(4 * 1024 * 1024).replace("\\\\", "\\")
        except (OSError, TypeError, ValueError):
            continue
        if all(token in text for token in (
            "Active Codex LOOP global mode",
            f"LOOP_CONTROL_ROOT={root}",
            "Mandatory LOOP model routing",
        )):
            return {
                "verified": True,
                "session_id": str(meta.get("id") or ""),
                "cwd": str(cwd),
                "rollout": str(path),
            }
    return {"verified": False}


def command_is_managed(hook: dict[str, Any]) -> bool:
    text = " ".join(str(hook.get(key, "")) for key in ("command", "commandWindows"))
    normalized = text.replace("/", "\\").casefold()
    return any(name.casefold() in normalized for name in MANAGED_SCRIPTS)


def strip_managed_hooks(doc: dict[str, Any]) -> dict[str, Any]:
    result = dict(doc) if isinstance(doc, dict) else {}
    hooks = result.get("hooks")
    if not isinstance(hooks, dict):
        hooks = {}
    cleaned: dict[str, list[dict[str, Any]]] = {}
    for event, groups in hooks.items():
        if not isinstance(groups, list):
            continue
        event_groups: list[dict[str, Any]] = []
        for group in groups:
            if not isinstance(group, dict):
                continue
            handlers = group.get("hooks")
            if not isinstance(handlers, list):
                event_groups.append(group)
                continue
            retained = [handler for handler in handlers
                        if not (isinstance(handler, dict) and command_is_managed(handler))]
            if retained:
                copy = dict(group)
                copy["hooks"] = retained
                event_groups.append(copy)
        if event_groups:
            cleaned[event] = event_groups
    result["hooks"] = cleaned
    return result


def merged_hooks(root: Path, codex_home: Path) -> dict[str, Any]:
    destination = read_json(codex_home / "hooks.json", {})
    if not isinstance(destination, dict):
        raise ValueError(f"global hooks file is not a JSON object: {codex_home / 'hooks.json'}")
    source = read_json(root / "config" / "global_hooks.json", None)
    if not isinstance(source, dict) or not isinstance(source.get("hooks"), dict):
        raise ValueError("managed global_hooks.json is invalid")
    merged = strip_managed_hooks(destination)
    hooks = merged.setdefault("hooks", {})
    for event, groups in source["hooks"].items():
        hooks.setdefault(event, []).extend(groups)
    managed_description = str(source.get("description") or "").strip()
    existing_description = str(merged.get("description") or "").strip()
    if existing_description and managed_description not in existing_description:
        merged["description"] = existing_description + " | " + managed_description
    elif existing_description:
        merged["description"] = existing_description
    else:
        merged["description"] = managed_description
    return merged


def ensure_backup(root: Path, codex_home: Path, install_state: Path) -> dict[str, Any]:
    existing = read_json(install_state, None)
    if isinstance(existing, dict) and existing.get("schema") == INSTALL_SCHEMA:
        # v1 installations created before managed hooks did not record
        # requirements.toml. Extend the immutable restore ledger before the
        # first managed write, preserving the exact current bytes if present.
        files = existing.setdefault("files", {})
        if "requirements.toml" not in files:
            source = codex_home / "requirements.toml"
            record: dict[str, Any] = {"existed": source.exists()}
            if source.exists():
                backup = Path(str(existing["backup_dir"])) / "requirements.toml"
                data = source.read_bytes()
                shutil.copy2(source, backup)
                record.update({"sha256": digest(data), "backup": str(backup)})
            files["requirements.toml"] = record
            atomic_write(install_state, json_bytes(existing))
        return existing
    # Microseconds plus PID prevent two first-time launchers in the same second
    # from selecting the same immutable backup directory.
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S-%f") + f"-{os.getpid()}"
    backup = root.parent / "backups" / "global-mode" / stamp
    backup.mkdir(parents=True, exist_ok=False)
    files: dict[str, dict[str, Any]] = {}
    for name in ("AGENTS.md", "hooks.json", "requirements.toml"):
        source = codex_home / name
        record: dict[str, Any] = {"existed": source.exists()}
        if source.exists():
            data = source.read_bytes()
            shutil.copy2(source, backup / name)
            record.update({"sha256": digest(data), "backup": str(backup / name)})
        files[name] = record
    doc = {
        "schema": INSTALL_SCHEMA,
        "installed_at": utc_now(),
        "control_root": str(root),
        "codex_home": str(codex_home),
        "backup_dir": str(backup),
        "files": files,
    }
    atomic_write(install_state, json_bytes(doc))
    return doc


def install(root: Path, codex_home: Path) -> dict[str, Any]:
    marker, install_state = state_paths(root)
    backup = ensure_backup(root, codex_home, install_state)
    # Remove prior LOOP user hooks so trusting them can never become an
    # accidental second execution path. The authoritative hooks are managed
    # inline by requirements.toml and therefore trusted by policy.
    existing_hooks = read_json(codex_home / "hooks.json", {})
    hooks = strip_managed_hooks(existing_hooks if isinstance(existing_hooks, dict) else {})
    requirements = managed_requirements(root)
    atomic_write(codex_home / "hooks.json", json_bytes(hooks))
    atomic_write(codex_home / "requirements.toml", requirements)
    atomic_write(codex_home / "AGENTS.md", NEUTRAL_AGENTS.encode("utf-8"))
    return {
        "installed": True,
        "control_root": str(root),
        "codex_home": str(codex_home),
        "marker": str(marker),
        "backup_dir": backup.get("backup_dir"),
        "agents_sha256": digest(NEUTRAL_AGENTS.encode("utf-8")),
        "hooks_sha256": digest(json_bytes(hooks)),
        "requirements_sha256": digest(requirements),
    }


def set_active(root: Path, codex_home: Path, active: bool) -> dict[str, Any]:
    marker, _ = state_paths(root)
    doc = {
        "schema": MODE_SCHEMA,
        "active": active,
        "control_root": str(root),
        "codex_home": str(codex_home),
        "updated_at": utc_now(),
        "scope": "all Desktop tasks regardless of target workspace" if active else "inactive",
    }
    atomic_write(marker, json_bytes(doc))
    return doc


def status(root: Path, codex_home: Path) -> dict[str, Any]:
    marker, install_state = state_paths(root)
    mode = read_json(marker, {})
    installed = read_json(install_state, {})
    declared_active = (
        isinstance(mode, dict) and mode.get("schema") == MODE_SCHEMA
        and mode.get("active") is True
    )
    requirements_expected = managed_requirements(root)
    requirements_path = codex_home / "requirements.toml"
    requirements_exact = (
        requirements_path.exists()
        and digest(requirements_path.read_bytes()) == digest(requirements_expected)
    )
    active_expected = active_agents(root)
    agents_active = (
        (codex_home / "AGENTS.md").exists()
        and digest((codex_home / "AGENTS.md").read_bytes()) == digest(active_expected)
    )
    context_verified = False
    spawn_gate_verified = False
    if declared_active and requirements_exact:
        try:
            context = subprocess.run(
                [sys.executable, str(root / "hooks" / "global_loop_mode.py"),
                 "--component", "context", "--event", "SessionStart"],
                input="{}", text=True, capture_output=True, timeout=15,
            )
            try:
                context_doc = json.loads(context.stdout)
                context_text = str(
                    context_doc["hookSpecificOutput"]["additionalContext"]
                )
            except (KeyError, TypeError, ValueError):
                context_text = ""
            context_verified = (
                context.returncode == 0
                and "Active Codex LOOP global mode" in context_text
                and f"LOOP_CONTROL_ROOT={root}" in context_text
                and "Mandatory LOOP model routing" in context_text
            )
            denied = subprocess.run(
                [sys.executable, str(root / "hooks" / "global_loop_mode.py"),
                 "--component", "spawn-gate"],
                input=json.dumps({
                    "tool_name": "multi_agent_v1__spawn_agent",
                    "session_id": "loop-install-canary-root",
                    "tool_input": {"fork_context": True},
                }),
                text=True, capture_output=True, timeout=15,
            )
            spawn_gate_verified = (
                denied.returncode == 0 and '"permissionDecision": "deny"' in denied.stdout
            )
        except (OSError, subprocess.SubprocessError):
            context_verified = False
            spawn_gate_verified = False
    effective_active = all((
        declared_active,
        requirements_exact,
        agents_active,
        context_verified,
        spawn_gate_verified,
    ))
    runtime = runtime_canary(root, codex_home, mode) if declared_active else {"verified": False}
    return {
        "installed": isinstance(installed, dict) and installed.get("schema") == INSTALL_SCHEMA,
        "active": declared_active,
        "declared_active": declared_active,
        "hooks_installed": requirements_exact,
        "hooks_trusted_or_managed": requirements_exact,
        "context_injection_verified": context_verified,
        "spawn_gate_verified": spawn_gate_verified,
        "active_agreement_present": agents_active,
        "effective_active": effective_active,
        "runtime_canary_verified": runtime.get("verified") is True,
        "runtime_canary_required": declared_active and runtime.get("verified") is not True,
        "runtime_canary": runtime,
        "control_root": str(root),
        "codex_home": str(codex_home),
        "marker": str(marker),
        "hooks_present": (codex_home / "hooks.json").exists(),
        "agents_present": (codex_home / "AGENTS.md").exists(),
    }


def restore(root: Path, codex_home: Path) -> dict[str, Any]:
    marker, install_state = state_paths(root)
    state = read_json(install_state, None)
    if not isinstance(state, dict) or state.get("schema") != INSTALL_SCHEMA:
        raise ValueError("no global LOOP installation backup is registered")
    if Path(str(state.get("codex_home", ""))).resolve() != codex_home:
        raise ValueError("registered CODEX_HOME does not match requested restore target")
    files = state.get("files", {})
    for name in ("AGENTS.md", "hooks.json", "requirements.toml"):
        record = files.get(name, {}) if isinstance(files, dict) else {}
        destination = codex_home / name
        if record.get("existed"):
            backup = Path(str(record["backup"]))
            data = backup.read_bytes()
            if digest(data) != record.get("sha256"):
                raise ValueError(f"backup hash mismatch for {name}")
            atomic_write(destination, data)
        else:
            destination.unlink(missing_ok=True)
    marker.unlink(missing_ok=True)
    install_state.unlink(missing_ok=True)
    return {"restored": True, "codex_home": str(codex_home), "backup_dir": state.get("backup_dir")}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("action", choices=("install", "activate", "deactivate", "status", "restore"))
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    parser.add_argument("--codex-home", type=Path,
                        default=Path(os.environ.get("CODEX_HOME", Path.home() / ".codex")))
    args = parser.parse_args()
    root = args.root.expanduser().resolve()
    codex_home = args.codex_home.expanduser().resolve()
    if args.action == "install":
        result = install(root, codex_home)
    elif args.action == "activate":
        installed = install(root, codex_home)
        mode = set_active(root, codex_home, True)
        atomic_write(codex_home / "AGENTS.md", active_agents(root))
        verified = status(root, codex_home)
        if not verified.get("effective_active"):
            set_active(root, codex_home, False)
            atomic_write(codex_home / "AGENTS.md", NEUTRAL_AGENTS.encode("utf-8"))
            raise RuntimeError(
                "LOOP activation failed effective-active verification: "
                + json.dumps(verified, ensure_ascii=False, sort_keys=True)
            )
        result = {"installation": installed, "mode": mode, "verification": verified}
    elif args.action == "deactivate":
        result = set_active(root, codex_home, False)
        atomic_write(codex_home / "AGENTS.md", NEUTRAL_AGENTS.encode("utf-8"))
    elif args.action == "restore":
        result = restore(root, codex_home)
    else:
        result = status(root, codex_home)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Launch a visible, lifecycle-supervised headless Codex wave.

This is the low-friction transport used when Desktop should remain a light
control plane.  It does not claim a birth from ``Popen`` alone: every task is
counted only after ``lifecycle_supervisor.py`` has published the matching
run-id as ``starting`` or ``running`` in ``exec_roster.json``.  The 8765
dashboard merges that roster with its WSL peer.

The input manifest is a JSON object with ``tasks``.  Each task needs
``task_id``, ``task_name``, ``prompt`` and ``cwd``; ``role`` defaults to
``worker``.  Concurrent workspace writes require explicitly distinct working
directories and ``allow_write=true``.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import time
import urllib.request
import uuid
from pathlib import Path
from typing import Any

try:
    from dispatch_v2 import (DispatcherV2, ExecutionPlane, ipybox_enabled_for,
                             resolve_role_pin)
    from lifecycle_supervisor import Store
    from orchestration_common import LoopPaths, OrchestrationPolicy, read_json
except ImportError:  # pragma: no cover
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from dispatch_v2 import (DispatcherV2, ExecutionPlane, ipybox_enabled_for,
                             resolve_role_pin)
    from lifecycle_supervisor import Store
    from orchestration_common import LoopPaths, OrchestrationPolicy, read_json


TASK_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,95}\Z")
ACTIVE = {"starting", "running"}
TERMINAL = {"completed", "failed", "timed_out", "cancelled", "spawn_failed", "lost"}
ROLE_SET = {"worker", "verifier", "reviewer", "plan_expander", "duty_officer"}


class WaveError(RuntimeError):
    pass


def load_manifest(path: Path) -> list[dict[str, Any]]:
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise WaveError(f"manifest unreadable: {exc}") from exc
    tasks = doc.get("tasks") if isinstance(doc, dict) else None
    if not isinstance(tasks, list) or not tasks:
        raise WaveError("manifest.tasks must be a non-empty list")
    seen: set[str] = set()
    write_cwds: set[str] = set()
    for index, task in enumerate(tasks):
        if not isinstance(task, dict):
            raise WaveError(f"task {index} is not an object")
        task_id = str(task.get("task_id") or "")
        if not TASK_ID.fullmatch(task_id) or task_id in seen:
            raise WaveError(f"invalid or duplicate task_id {task_id!r}")
        seen.add(task_id)
        packet_id = task.get("packet_id")
        if packet_id is not None:
            if not isinstance(packet_id, str) or not TASK_ID.fullmatch(packet_id):
                raise WaveError(f"task {task_id}: invalid packet_id")
            required = ("task_name",)
        else:
            required = ("task_name", "prompt", "cwd")
        for key in required:
            if not isinstance(task.get(key), str) or not task[key].strip():
                raise WaveError(f"task {task_id}: missing {key}")
        role = str(task.get("role") or "worker")
        if role not in ROLE_SET:
            raise WaveError(f"task {task_id}: unsupported role {role!r}")
        sandbox = str(task.get("sandbox") or "read-only")
        if sandbox not in {"read-only", "workspace-write"}:
            raise WaveError(f"task {task_id}: unsupported sandbox {sandbox!r}")
        if packet_id is not None and any(
                key in task for key in ("prompt", "cwd", "sandbox", "allow_write")):
            raise WaveError(f"task {task_id}: packet tasks may not override execution details")
        if sandbox == "workspace-write":
            if task.get("allow_write") is not True:
                raise WaveError(f"task {task_id}: workspace-write needs allow_write=true")
            cwd = str(Path(task["cwd"]).resolve()).casefold()
            if cwd in write_cwds:
                raise WaveError("workspace-write tasks must use distinct cwd values")
            write_cwds.add(cwd)
    return tasks


def roster_item(data_dir: Path, packet_id: str) -> dict[str, Any]:
    doc = read_json(data_dir / "lifecycle" / "exec_roster.json", {}) or {}
    row = (doc.get("jobs") or {}).get(packet_id)
    return row if isinstance(row, dict) else {}


def process_start_token(pid: Any) -> int | None:
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        handle = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
        if not handle:
            return None
        try:
            code = wintypes.DWORD()
            if (not ctypes.windll.kernel32.GetExitCodeProcess(
                    handle, ctypes.byref(code)) or code.value != 259):
                return None
            creation = wintypes.FILETIME(); exit_time = wintypes.FILETIME()
            kernel = wintypes.FILETIME(); user = wintypes.FILETIME()
            if not ctypes.windll.kernel32.GetProcessTimes(
                    handle, ctypes.byref(creation), ctypes.byref(exit_time),
                    ctypes.byref(kernel), ctypes.byref(user)):
                return None
            return ((int(creation.dwHighDateTime) << 32)
                    | int(creation.dwLowDateTime))
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    try:
        return int(Path("/proc/%d/stat" % pid).read_text(
            encoding="ascii").split()[21])
    except (OSError, ValueError, IndexError):
        return None


def process_alive(pid: Any, expected_start: Any = None) -> bool:
    actual = process_start_token(pid)
    if actual is None:
        return False
    if expected_start is None:
        return True
    try:
        return actual == int(expected_start)
    except (TypeError, ValueError):
        return False


def recover_live_supervisor(data_dir: Path, packet_id: str) -> dict[str, Any]:
    row = roster_item(data_dir, packet_id)
    published = row.get("published_report")
    if (row.get("state") == "lost" and row.get("exit_code") == 0
            and isinstance(published, str) and Path(published).is_file()):
        return Store(data_dir).update(
            packet_id, run_id=str(row.get("run_id") or ""),
            attempt=int(row.get("attempt", 0) or 0), state="completed",
            recovered_by="headless_wave_completed_report")
    if (row.get("state") not in ACTIVE and row.get("run_id")
            and process_alive(row.get("supervisor_pid"),
                              row.get("supervisor_proc_start_ticks"))
            and process_alive(row.get("os_pid"),
                              row.get("worker_proc_start_ticks"))):
        return Store(data_dir).update(
            packet_id, run_id=str(row["run_id"]),
            attempt=int(row.get("attempt", 0) or 0), state="running",
            heartbeat_at=time.time(), recovered_by="headless_wave")
    return row


def observed(data_dir: Path, packet_id: str, run_id: str) -> bool:
    row = roster_item(data_dir, packet_id)
    # Only RUNNING is effective concurrency.  ``starting`` merely reserves an
    # initializing slot and may be followed by spawn_failed milliseconds later.
    return row.get("run_id") == run_id and row.get("state") == "running"


def wait_observed(data_dir: Path, packet_id: str, run_id: str,
                  timeout: float = 5.0, stable_for: float = 0.25) -> bool:
    deadline = time.monotonic() + timeout
    first_running: float | None = None
    while time.monotonic() < deadline:
        row = roster_item(data_dir, packet_id)
        if row.get("run_id") != run_id:
            first_running = None
        elif row.get("state") == "running":
            first_running = first_running or time.monotonic()
            if time.monotonic() - first_running >= stable_for:
                return True
        else:
            first_running = None
            if row.get("state") in {"completed", "failed", "timed_out", "cancelled",
                                    "spawn_failed"}:
                return False
        time.sleep(0.05)
    return False


def wait_generation_change(data_dir: Path, packet_id: str, prior_run_id: str,
                           timeout: float = 5.0) -> dict[str, Any]:
    """Wait until the packet-keyed roster is overwritten by the new birth."""
    deadline = time.monotonic() + timeout
    latest: dict[str, Any] = {}
    while time.monotonic() < deadline:
        latest = roster_item(data_dir, packet_id)
        run_id = str(latest.get("run_id") or "")
        if run_id and run_id != prior_run_id:
            return latest
        time.sleep(0.05)
    return latest


def _completion_fields(row: dict[str, Any]) -> dict[str, Any]:
    """Project terminal lifecycle data into a bounded parent-facing result.

    The full report remains on disk.  Returning only its path and a bounded
    first line preserves the Fable return convention without injecting a
    completed wave's full context into the parent Desktop turn.
    """
    report = row.get("published_report") or row.get("report")
    result: dict[str, Any] = {}
    if isinstance(report, str) and report:
        result["report_path"] = report
        try:
            text = Path(report).read_text(encoding="utf-8", errors="replace")
            lines = [line.strip() for line in text.splitlines() if line.strip()]
            if lines:
                result["summary"] = lines[0][:500]
        except OSError:
            pass
    if row.get("failure") is not None:
        result["failure"] = row.get("failure")
    return result


def wait_for_terminal(data_dir: Path, results: list[dict[str, Any]],
                      timeout: float) -> None:
    """Block the parent wave until its observed generations are terminal.

    This is deliberately a deterministic supervisor wait, not an LLM/Sol
    polling round.  Parent-bound waves use it by default so the calling
    Desktop turn remains open long enough to receive child reports.  A caller
    that intentionally wants detached background work must pass ``--detach``.
    """
    pending = {
        index for index, result in enumerate(results)
        if result.get("status") in {"running", "already_active"}
        and result.get("packet_id") and result.get("run_id")
    }
    if not pending:
        return
    deadline = time.monotonic() + max(0.0, float(timeout))
    while pending:
        progressed = False
        for index in tuple(pending):
            result = results[index]
            row = recover_live_supervisor(data_dir, str(result["packet_id"]))
            expected_run = result.get("run_id")
            evidence = row if row.get("run_id") == expected_run else {}
            if not evidence:
                # A newer generation may already own the packet-keyed live
                # row.  Terminal history is keyed by immutable run_id and is
                # therefore the authoritative ABA-safe completion source.
                for history_row in reversed(row.get("history") or []):
                    if (isinstance(history_row, dict)
                            and history_row.get("run_id") == expected_run
                            and history_row.get("state") in TERMINAL):
                        evidence = history_row
                        break
            state = str(evidence.get("state") or "")
            if state not in TERMINAL:
                continue
            result["status"] = state
            result.update(_completion_fields(evidence))
            pending.remove(index)
            progressed = True
        if not pending:
            return
        if time.monotonic() >= deadline:
            for index in pending:
                results[index]["status"] = "wait_timeout"
                results[index]["failure"] = {
                    "reason": "parent_wave_wait_timeout",
                    "timeout_seconds": timeout,
                }
            return
        if not progressed:
            time.sleep(0.20)


def resolve_codex_binary() -> str:
    explicit = os.environ.get("CODEX_HEADLESS_BIN")
    if explicit:
        path = Path(explicit).resolve()
        if path.is_file():
            return str(path)
        raise WaveError(f"CODEX_HEADLESS_BIN is not a file: {path}")
    if os.name == "nt":
        npm_vendor = (Path.home() / "AppData" / "Roaming" / "npm" / "node_modules"
                      / "@openai" / "codex" / "node_modules" / "@openai"
                      / "codex-win32-x64" / "vendor" / "x86_64-pc-windows-msvc"
                      / "bin" / "codex.exe")
        if npm_vendor.is_file():
            return str(npm_vendor)
        candidate = shutil.which("codex.exe")
    else:
        candidate = shutil.which("codex")
    if not candidate:
        raise WaveError("headless codex executable not found")
    return candidate


def opencodex_healthy() -> bool:
    try:
        with urllib.request.urlopen("http://127.0.0.1:10100/healthz", timeout=2.0) as response:
            value = json.loads(response.read(65536).decode("utf-8"))
        return response.status == 200 and value.get("status") == "ok"
    except Exception:
        return False


def provider_birth_allowed(root: Path, model: str) -> bool:
    from provider_health import backoff_active
    blocked, _ = backoff_active(root, model)
    return not blocked


def launch_supervisor(command: list[str], root: Path, log_path: Path) -> int:
    log_path.parent.mkdir(parents=True, exist_ok=True)
    log = log_path.open("ab")
    kwargs: dict[str, Any] = {
        "cwd": str(root), "stdin": subprocess.DEVNULL,
        "stdout": log, "stderr": subprocess.STDOUT, "close_fds": True,
    }
    if os.name == "nt":
        kwargs["creationflags"] = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                                   | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
    else:
        kwargs["start_new_session"] = True
    try:
        proc = subprocess.Popen(command, **kwargs)
        return proc.pid
    finally:
        log.close()


def task_key(manifest: Path, task_id: str) -> str:
    digest = hashlib.sha256(str(manifest.resolve()).encode("utf-8")).hexdigest()[:10]
    return f"adhoc-{digest}-{task_id}"[:96]


def build_commands(task: dict[str, Any], manifest: Path, paths: LoopPaths,
                   policy: OrchestrationPolicy, timeout: float) -> tuple[str, str, list[str], list[str], Path]:
    role = str(task.get("role") or "worker")
    pin = resolve_role_pin(role, paths, policy)
    sandbox = str(task.get("sandbox") or "read-only")
    packet_id = task_key(manifest, str(task["task_id"]))
    run_id = f"{packet_id}-{uuid.uuid4().hex}"
    report_dir = paths.data / "reports" / "headless-wave" / packet_id / run_id
    report = report_dir / "last_message.txt"
    events = report_dir / "events.jsonl"
    stderr = report_dir / "stderr.log"
    ipybox = ipybox_enabled_for(role, ExecutionPlane.WSL_HEADLESS, policy, task)
    prompt = (
        "You are a leaf LOOP agent. Do not spawn, delegate to, create, or "
        "message any subagent/thread, and do not call multi-agent tools. "
        "Complete this bounded packet yourself and return directly to the "
        "orchestrator.\n" + str(task["prompt"])
    )
    if not prompt.lstrip().startswith("浠诲姟鍚嶏細"):
        prompt = f"浠诲姟鍚嶏細{task['task_name']}\n{prompt}"
    worker = [resolve_codex_binary(), "exec", "--skip-git-repo-check", "--sandbox", sandbox,
              *pin.cli_overrides(), "-c",
              f"mcp_servers.ipybox.enabled={'true' if ipybox else 'false'}"]
    # The Desktop Windows config contains a complete node_repl transport and
    # needs an explicit headless disable.  WSL has no node_repl table; adding
    # only `enabled=false` would create an invalid transport at config-parse
    # time, so absence already is the desired disabled state.
    if os.name == "nt":
        worker += ["-c", "mcp_servers.node_repl.enabled=false"]
    # Headless source/audit packets do not need the Desktop Apps/plugin plane.
    # Disabling it avoids remote plugin/MCP authentication retries on every
    # birth. A bounded manifest may opt in for a task that genuinely needs it.
    if task.get("enable_apps") is not True:
        worker += ["-c", "features.apps=false",
                   "-c", "features.plugins=false",
                   "-c", "features.recommended_plugins=false",
                   "-c", "features.remote_plugin=false"]
    worker += ["--json", "-o", str(report), prompt]
    supervisor = [sys.executable, str(paths.root / "harness" / "lifecycle_supervisor.py"),
                  "--data-dir", str(paths.data), "--packet", packet_id,
                  "--run-id", run_id, "--attempt", "0",
                  *(["--parent-session-id", str(task["parent_session_id"])]
                    if task.get("parent_session_id") else []),
                  *(["--manifest-id", str(task["manifest_id"])]
                    if task.get("manifest_id") else []),
                  "--task-name", str(task["task_name"])[:160], "--role", role,
                  "--model", pin.model, "--plane",
                  "Windows CLI" if os.name == "nt" else "WSL CLI",
                  "--cwd", str(Path(task["cwd"]).resolve()),
                  "--stdout", str(events), "--stderr", str(stderr),
                  "--report", str(report), "--timeout", str(timeout), "--", *worker]
    return packet_id, run_id, supervisor, worker, report_dir


def run(args: argparse.Namespace) -> int:
    manifest = args.manifest.resolve()
    paths = LoopPaths.resolve(args.root)
    policy = OrchestrationPolicy.load(paths)
    tasks = load_manifest(manifest)
    detach = bool(getattr(args, "detach", False))
    explicit_wait = bool(getattr(args, "wait_all", False))
    if detach and explicit_wait:
        raise WaveError("--detach and --wait-all are mutually exclusive")
    # Parent-bound waves restore the Fable/native wait-all contract by
    # default.  Unparented operational waves retain the old detached behavior
    # unless the caller opts into --wait-all explicitly.
    wait_all = explicit_wait or (
        not detach and any(task.get("parent_session_id") for task in tasks))
    interval = max(0.0, args.spawn_interval_ms / 1000.0)
    results: list[dict[str, Any]] = []
    dispatcher = DispatcherV2(paths)
    for index, task in enumerate(tasks, 1):
        task_id = str(task["task_id"])
        if task.get("packet_id") is not None:
            packet_id = str(task["packet_id"])
            role = str(task.get("role") or "worker")
            ledger = read_json(paths.ledger, {"packets": {}}) or {"packets": {}}
            entry = (ledger.get("packets") or {}).get(packet_id)
            allowed_states = {"DISPATCHABLE"}
            if not isinstance(entry, dict) or entry.get("state") not in allowed_states:
                results.append({"task_id": task["task_id"],
                                "status": "ledger_state_blocked",
                                "packet_id": packet_id,
                                "ledger_state": (entry or {}).get("state")
                                if isinstance(entry, dict) else None})
                continue
            expected_model = resolve_role_pin(role, paths, policy).model
            prior = recover_live_supervisor(paths.data, packet_id)
            if prior.get("state") in ACTIVE and not (
                    process_alive(prior.get("supervisor_pid"),
                                  prior.get("supervisor_proc_start_ticks"))
                    and process_alive(prior.get("os_pid"),
                                      prior.get("worker_proc_start_ticks"))):
                results.append({"task_id": task["task_id"],
                                "status": "stale_active_roster",
                                "packet_id": packet_id,
                                "run_id": prior.get("run_id")})
                continue
            if prior.get("state") in ACTIVE and (
                    prior.get("role") != role or prior.get("model") != expected_model):
                results.append({"task_id": task["task_id"],
                                "status": "active_route_conflict",
                                "packet_id": packet_id,
                                "observed_role": prior.get("role"),
                                "observed_model": prior.get("model")})
                continue
            if prior.get("state") == "running":
                results.append({"task_id": task["task_id"], "status": "already_active",
                                "packet_id": packet_id, "run_id": prior.get("run_id")})
                continue
            if prior.get("state") == "starting":
                prior_run = str(prior.get("run_id") or "")
                if prior_run and wait_observed(paths.data, packet_id, prior_run,
                                               args.observe_timeout):
                    results.append({"task_id": task["task_id"],
                                    "status": "already_active",
                                    "packet_id": packet_id, "run_id": prior_run})
                else:
                    final = roster_item(paths.data, packet_id)
                    results.append({"task_id": task["task_id"],
                                    "status": str(final.get("state") or "initializing"),
                                    "packet_id": packet_id, "run_id": prior_run,
                                    "failure": final.get("failure")})
                continue
            if args.dry_run:
                rc = dispatcher.dispatch([packet_id], role=role, dry_run=True,
                                         wave_idx=index - 1)
                results.append({"task_id": task["task_id"],
                                "status": "dry_run" if rc == 0 else "dispatch_refused",
                                "packet_id": packet_id, "role": role})
                continue
            # Backoff is a birth gate, not a status/read-only gate: dry-runs
            # and already-active generations above remain observable.
            if not provider_birth_allowed(paths.root, expected_model):
                results.append({"task_id": task_id, "status": "provider_backoff",
                                "model": expected_model})
                continue
            if index > 1 and interval:
                time.sleep(interval)
            if index == 1 or (index - 1) % max(1, args.health_every) == 0:
                if not opencodex_healthy():
                    results.append({"task_id": task["task_id"],
                                    "status": "health_blocked",
                                    "packet_id": packet_id})
                    continue
            prior_run = str(prior.get("run_id") or "")
            rc = dispatcher.dispatch([packet_id], role=role, dry_run=False,
                                     wave_idx=index - 1)
            fresh = (wait_generation_change(paths.data, packet_id, prior_run,
                                            args.observe_timeout)
                     if rc == 0 else roster_item(paths.data, packet_id))
            run_id = str(fresh.get("run_id") or "")
            if rc == 0 and run_id and run_id != prior_run and wait_observed(
                    paths.data, packet_id, run_id, args.observe_timeout):
                results.append({"task_id": task["task_id"], "status": "running",
                                "packet_id": packet_id, "run_id": run_id})
            else:
                final = roster_item(paths.data, packet_id)
                results.append({"task_id": task["task_id"],
                                "status": ("dispatch_refused" if rc else
                                           str(final.get("state") or "unobserved")),
                                "packet_id": packet_id, "run_id": run_id,
                                "failure": final.get("failure")})
            continue
        packet_id, run_id, supervisor, worker, report_dir = build_commands(
            task, manifest, paths, policy, args.timeout)
        prior = recover_live_supervisor(paths.data, packet_id)
        if prior.get("state") == "completed":
            results.append({"task_id": task["task_id"], "status": "already_completed",
                            "packet_id": packet_id, "run_id": prior.get("run_id")})
            continue
        if prior.get("state") == "running":
            results.append({"task_id": task["task_id"], "status": "already_active",
                            "packet_id": packet_id, "run_id": prior.get("run_id")})
            continue
        if prior.get("state") == "starting":
            prior_run = str(prior.get("run_id") or "")
            if prior_run and wait_observed(paths.data, packet_id, prior_run,
                                           args.observe_timeout):
                results.append({"task_id": task["task_id"], "status": "already_active",
                                "packet_id": packet_id, "run_id": prior_run})
            else:
                final = roster_item(paths.data, packet_id)
                results.append({"task_id": task["task_id"],
                                "status": str(final.get("state") or "initializing"),
                                "packet_id": packet_id, "run_id": prior_run,
                                "failure": final.get("failure")})
            continue
        if args.dry_run:
            results.append({"task_id": task["task_id"], "status": "dry_run",
                            "packet_id": packet_id, "model": worker[worker.index("-m") + 1]})
            continue
        expected_model = worker[worker.index("-m") + 1]
        if not provider_birth_allowed(paths.root, expected_model):
            results.append({"task_id": task_id, "status": "provider_backoff",
                            "packet_id": packet_id, "model": expected_model})
            continue
        if index > 1 and interval:
            time.sleep(interval)
        if index == 1 or (index - 1) % max(1, args.health_every) == 0:
            if not opencodex_healthy():
                results.append({"task_id": task["task_id"], "status": "health_blocked",
                                "packet_id": packet_id})
                continue
        supervisor_pid = launch_supervisor(
            supervisor, paths.root, report_dir / "supervisor.log")
        if wait_observed(paths.data, packet_id, run_id, args.observe_timeout):
            results.append({"task_id": task["task_id"], "status": "running",
                            "packet_id": packet_id, "run_id": run_id,
                            "supervisor_pid": supervisor_pid})
        else:
            # Unknown is deliberately not counted as a successful handoff and
            # must not clear any external refill debt.  Do not auto-retry: the
            # supervisor may still be starting, and retrying could duplicate.
            final = roster_item(paths.data, packet_id)
            results.append({"task_id": task["task_id"],
                            "status": str(final.get("state") or "unobserved"),
                            "packet_id": packet_id, "run_id": run_id,
                            "supervisor_pid": supervisor_pid,
                            "failure": final.get("failure")})
    if wait_all and not args.dry_run:
        wait_for_terminal(paths.data, results, args.timeout + 30.0)
    print(json.dumps({"manifest": str(manifest), "target_requested": len(tasks),
                      "observed_running": sum(r["status"] in {"running", "already_active"}
                                              for r in results),
                      "wait_all": wait_all,
                      "results": results}, ensure_ascii=False))
    return 0 if all(r["status"] in {"running", "already_active", "already_completed",
                                       "completed", "dry_run"}
                    for r in results) else 3


def parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(description="Launch a lifecycle-visible headless Codex wave")
    ap.add_argument("--manifest", type=Path, required=True)
    ap.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    ap.add_argument("--timeout", type=float, default=1800.0)
    ap.add_argument("--observe-timeout", type=float, default=5.0)
    ap.add_argument("--spawn-interval-ms", type=int, default=1000)
    ap.add_argument("--health-every", type=int, default=8)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--wait-all", action="store_true",
                    help="wait for all observed generations to reach terminal state")
    ap.add_argument("--detach", action="store_true",
                    help="return after birth observation; only for intentional background waves")
    return ap


if __name__ == "__main__":
    raise SystemExit(run(parser().parse_args()))

#!/usr/bin/env python3
"""orchestration_common.py 鈥?Shared foundation for the codex-loop-s-f2 redesign.

This module is the single home for the primitives every new orchestration
component needs:

* cross-platform (Windows / WSL / POSIX) path resolution via :mod:`pathlib`;
* a one-byte advisory file lock that works with both ``msvcrt`` and ``fcntl``;
* atomic JSON read/write and locked NDJSON append helpers;
* fail-closed policy loading for ``config/orchestration_policy_v2.toml`` and
  ``config/refill_policy.toml`` (design invariant 3: single source of truth,
  policy unreadable => fail visible, never a silent divergent default);
* model-pin resolution 鈥?models are read from configuration, **never**
  hardcoded (fixes the "hand-copied model name" class of defect; the current
  the current temporary deployment pins execution = ``weiwu-k3/kimi-k3`` and
  K3 = ``weiwu-k3/kimi-k3`` in config, but this module does not assume that);
* semantic idempotency keys (the V10 ``k3IdemKey`` pattern from
  ``verification_kernel-11.md 搂4.1``).

Every component under ``impl/harness/`` imports from here; the module has no
dependencies outside the Python 3.10+ standard library.
"""
from __future__ import annotations

import base64
import contextlib
import hashlib
import json
import logging
import os
import sys
import time
import tomllib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterator, Mapping

__all__ = [
    "PolicyError",
    "ModelPinError",
    "LoopPaths",
    "file_lock",
    "read_json",
    "atomic_write_json",
    "append_ndjson",
    "iter_ndjson",
    "OrchestrationPolicy",
    "canonical_policy_path",
    "policy_sha256",
    "layered_authorization",
    "RefillPolicy",
    "idem_key",
    "get_logger",
    "utc_now",
]

_LOG_FORMAT = "%(asctime)s %(name)s %(levelname)s %(message)s"


def get_logger(name: str) -> logging.Logger:
    """Return a configured logger.  Handlers are attached once per process."""
    logger = logging.getLogger(name)
    if not logging.getLogger().handlers and not logger.handlers:
        handler = logging.StreamHandler(sys.stderr)
        handler.setFormatter(logging.Formatter(_LOG_FORMAT))
        logger.addHandler(handler)
        logger.setLevel(os.environ.get("LOOP_LOG_LEVEL", "INFO").upper())
    return logger


log = get_logger("loop.common")


class PolicyError(RuntimeError):
    """A policy file is missing or malformed.

    Raised instead of falling back to silent divergent defaults 鈥?the P0-8.3
    fix direction: policy unreadable => fail closed and visible.
    """


class ModelPinError(PolicyError):
    """A required model pin could not be resolved from configuration."""


def canonical_policy_path(root: Path | str) -> Path:
    """Return the sole production orchestration-policy path."""
    return Path(root).resolve() / "config" / "orchestration_policy_v2.toml"


def policy_sha256(path: Path | str) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def layered_authorization(root: Path | str, *, now: float | None = None,
                          max_age_s: float = 3600) -> tuple[bool, str]:
    """Validate that layered authorization is fresh and byte-bound."""
    root = Path(root).resolve()
    marker_path = root / "data" / "governor" / "layered_authorization.json"
    policy_path = canonical_policy_path(root)
    try:
        marker = json.loads(marker_path.read_text(encoding="utf-8"))
        age = (time.time() if now is None else now) - float(marker["ts"])
        current_hash = policy_sha256(policy_path)
        conditions = marker["conditions"]
    except (OSError, ValueError, KeyError, TypeError) as exc:
        return False, f"authorization unreadable: {exc}"
    if marker.get("status") != "PASS" or marker.get("authorized_mode") != "layered":
        return False, "authorization status/mode mismatch"
    if age < 0 or age > max_age_s:
        return False, f"authorization age={age:.1f}s exceeds {max_age_s:.1f}s"
    if marker.get("policy_sha256") != current_hash:
        return False, "authorization policy hash mismatch"
    if not isinstance(conditions, list) or not conditions or not all(
            isinstance(item, dict) and bool(item.get("ok"))
            for item in conditions):
        return False, "authorization conditions incomplete"
    return True, f"authorization current age={age:.1f}s"


def utc_now() -> float:
    """Wall-clock epoch seconds (single definition so tests can monkeypatch)."""
    return time.time()


# ---------------------------------------------------------------------------
# Paths 鈥?Windows/WSL compatible.  All joins go through pathlib; no separator
# is ever hardcoded (task constraint: cross-platform path compatibility).
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class LoopPaths:
    """Resolved directory layout for one LOOP root.

    ``root`` honours ``$LOOP_ROOT`` when constructed via :meth:`resolve`,
    falling back to the package root two levels above this file.
    """

    root: Path

    @classmethod
    def resolve(cls, root: Path | str | None = None) -> "LoopPaths":
        """Resolve the LOOP root: explicit arg > $LOOP_ROOT > package root."""
        if root is not None:
            return cls(Path(root).resolve())
        env = os.environ.get("LOOP_ROOT")
        if env:
            return cls(Path(env).resolve())
        return cls(Path(__file__).resolve().parents[1])

    # -- directories --------------------------------------------------------
    @property
    def data(self) -> Path:
        return self.root / "data"

    @property
    def config(self) -> Path:
        return self.root / "config"

    @property
    def events(self) -> Path:
        return self.data / "events.ndjson"

    @property
    def events_lock(self) -> Path:
        return self.data / "lifecycle" / ".events.lock"

    @property
    def ledger(self) -> Path:
        return self.data / "progress_ledger.json"

    @property
    def l2_queue_dir(self) -> Path:
        return self.data / "l2_queue"

    @property
    def l2_pending(self) -> Path:
        return self.l2_queue_dir / "pending.ndjsonl"

    @property
    def l2_claims_dir(self) -> Path:
        return self.l2_queue_dir / "claims"

    @property
    def l2_heartbeat(self) -> Path:
        return self.l2_queue_dir / "consumer_heartbeat.json"

    @property
    def governor_dir(self) -> Path:
        return self.data / "governor"

    @property
    def budget_dir(self) -> Path:
        return self.data / "budget"

    @property
    def router_dir(self) -> Path:
        return self.data / "router"

    @property
    def usage_dir(self) -> Path:
        return self.data / "usage"

    @property
    def refill_dir(self) -> Path:
        return self.data / "refill"

    @property
    def meter_report(self) -> Path:
        """Resolve the newest meter contract before compatibility fallbacks.

        ``model_token_share_v2.py`` writes ``model_token_share_v2.json``.
        Older F2 components used ``meter_v2_report.json`` and v1 used
        ``model_token_share.json``; keep those readable in that order without
        pointing the governor at a path that no producer writes.
        """
        candidates = (
            self.usage_dir / "model_token_share_v2.json",
            self.usage_dir / "meter_v2_report.json",
            self.usage_dir / "model_token_share.json",
        )
        return next((path for path in candidates if path.exists()), candidates[0])

    @property
    def token_ledger(self) -> Path:
        return self.usage_dir / "token_ledger.ndjsonl"

    @property
    def run_role_map(self) -> Path:
        return self.usage_dir / "run_role_map.json"


# ---------------------------------------------------------------------------
# Locking / atomic IO
# ---------------------------------------------------------------------------
@contextlib.contextmanager
def file_lock(path: Path) -> Iterator[None]:
    """Cross-process one-byte advisory lock (same protocol the shipped
    ``lifecycle_supervisor.locked`` uses, so v2 components interoperate with
    v1 writers on the same lock files)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0")
            handle.flush()
        handle.seek(0)
        if os.name == "nt":  # pragma: no cover - Windows plane
            import msvcrt

            msvcrt.locking(handle.fileno(), msvcrt.LK_LOCK, 1)
        else:
            import fcntl

            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":  # pragma: no cover - Windows plane
                import msvcrt

                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def read_json(path: Path | str, default: Any = None) -> Any:
    """Read JSON, returning ``default`` on any IO/parse failure."""
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def atomic_write_json(path: Path | str, value: Any) -> None:
    """Write JSON atomically (tmp file + ``os.replace``); fsynced."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
    with tmp.open("w", encoding="utf-8", newline="\n") as handle:
        json.dump(value, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def append_ndjson(path: Path | str, obj: Mapping[str, Any],
                  lock_path: Path | None = None) -> None:
    """Append one JSON line under an advisory lock (append-only ledger)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = lock_path if lock_path is not None else path.with_suffix(path.suffix + ".lock")
    with file_lock(lock):
        with path.open("a", encoding="utf-8", newline="\n") as handle:
            handle.write(json.dumps(obj, ensure_ascii=False,
                                    separators=(",", ":")) + "\n")


def iter_ndjson(path: Path | str) -> Iterator[dict[str, Any]]:
    """Yield parsed records from an NDJSON file; malformed lines are skipped
    with a warning (fail-visible via log, never a crash)."""
    path = Path(path)
    if not path.exists():
        return
    with path.open(encoding="utf-8") as handle:
        for lineno, line in enumerate(handle, 1):
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except ValueError:
                log.warning("iter_ndjson: %s:%d unparseable line skipped", path, lineno)
                continue
            if isinstance(rec, dict):
                yield rec


# ---------------------------------------------------------------------------
# Semantic idempotency keys (V10 k3IdemKey pattern)
# ---------------------------------------------------------------------------
def idem_key(kind: str, scope: str, *semantic_fields: str) -> str:
    """Build ``k3:<kind>:<scope>:<b32(sha256(fields))[:16]>``.

    The key is derived from *semantic* fields (never timestamps), so the same
    logical request always maps to the same key 鈥?the exactly-once boundary
    for the l2 consumer and every append-only ledger record.
    """
    digest = hashlib.sha256("|".join(semantic_fields).encode("utf-8")).digest()
    suffix = base64.b32encode(digest).decode("ascii").lower().rstrip("=")[:16]
    return f"k3:{kind}:{scope}:{suffix}"


# ---------------------------------------------------------------------------
# Policy loading 鈥?fail-closed
# ---------------------------------------------------------------------------
def _load_toml(path: Path, what: str) -> dict[str, Any]:
    if not path.exists():
        raise PolicyError(f"{what} missing: {path} 鈥?refusing silent defaults "
                          f"(P0-8.3 fail-closed policy reads)")
    try:
        with path.open("rb") as handle:
            return tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise PolicyError(f"{what} unreadable: {path}: {exc}") from exc


@dataclass
class OrchestrationPolicy:
    """Typed view over the canonical ``config/orchestration_policy_v2.toml``.

    Declaration face = enforcement face (design invariant 2): every limit the
    file declares is read here and enforced by the component that owns it.
    Concurrency numbers are **not** duplicated here 鈥?they live only in
    ``refill_policy.toml`` (invariant 3); this policy carries a
    ``refill_policy_ref`` key instead.
    """

    doc: dict[str, Any] = field(default_factory=dict)
    path: Path | None = None

    @classmethod
    def load(cls, paths: LoopPaths | None = None) -> "OrchestrationPolicy":
        paths = paths or LoopPaths.resolve()
        # The policy path is intentionally not environment-overridable.  A
        # process-local override created a second production authority: typed
        # consumers could see a different routing mode and model pin from the
        # hooks, meter and layered gate.  Tests that need a synthetic policy
        # construct OrchestrationPolicy directly inside their isolated root.
        policy_path = canonical_policy_path(paths.root)
        return cls(_load_toml(policy_path, "orchestration policy"), policy_path)

    # -- generic accessors ----------------------------------------------------
    def value(self, section: str, key: str, default: Any = None) -> Any:
        table = self.doc.get(section, {})
        return table.get(key, default) if isinstance(table, dict) else default

    def require(self, section: str, key: str) -> Any:
        value = self.value(section, key, None)
        if value is None:
            raise PolicyError(
                f"orchestration policy [{section}].{key} missing in {self.path} "
                f"鈥?fail-closed (declaration face = enforcement face)")
        return value

    # -- routing ---------------------------------------------------------------
    def routing_mode(self) -> str:
        """``cold_start`` | ``shadow`` | ``layered``.

        ``passthrough_enabled`` (legacy boolean) is honoured only as an alias:
        ``false -> cold_start``, ``true -> layered``.  Missing everything =>
        cold_start (safe default, byte-identical legacy behavior).
        """
        mode = self.value("routing", "mode")
        if isinstance(mode, str) and mode in ("cold_start", "shadow", "layered"):
            return mode
        legacy = self.value("routing", "passthrough_enabled")
        if isinstance(legacy, bool):
            return "layered" if legacy else "cold_start"
        return "cold_start"

    def verify_sample_rate(self) -> float:
        value = self.value("routing", "verify_sample_rate", 0.10)
        return float(value) if isinstance(value, (int, float)) else 0.10

    # -- model pins --------------------------------------------------------------
    def model_pin(self, role_family: str) -> str:
        """Resolve the model id for a role family (``sol`` / ``k3`` / ``v4``).

        Read from ``[models]``; missing pin raises :class:`ModelPinError` 鈥?        silently falling back to a hardcoded model string is exactly the
        defect class being fixed (task constraint: never hardcode
        ``deepseek-v4-flash`` or any other model id in code).
        """
        models = self.doc.get("models", {})
        key = f"{role_family}_model"
        pin = models.get(key) if isinstance(models, dict) else None
        if not isinstance(pin, str) or not pin:
            raise ModelPinError(
                f"orchestration policy [models].{role_family} missing in "
                f"{self.path}; refusing to guess a model id (fail-visible)")
        return pin

    def model_context(self, role_family: str, key: str) -> int | None:
        """Optional context sizing from the canonical flat ``[models]`` keys."""
        suffix = {"context_window": "context_tokens",
                  "compaction": "compaction_tokens"}.get(key)
        models = self.doc.get("models", {})
        value = models.get(f"{role_family}_{suffix}") \
            if isinstance(models, dict) and suffix else None
        return int(value) if isinstance(value, int) and not isinstance(value, bool) else None

    def model_reasoning(self, role_family: str) -> str | None:
        models = self.doc.get("models", {})
        value = models.get(f"{role_family}_reasoning") \
            if isinstance(models, dict) else None
        return value if isinstance(value, str) and value else None

    # -- token bands / hysteresis ---------------------------------------------------
    def sol_hard_cap(self) -> float:
        return float(self.value("tokens", "sol_allocation_cap",
                                self.value("tokens", "sol_hard_cap", 0.15)))

    def k3_floor(self) -> float:
        return float(self.value("tokens", "k3_floor", 0.20))

    def minimum_denominator(self) -> int:
        return int(self.value("tokens", "minimum_denominator", 2_000_000))

    def hysteresis(self) -> dict[str, float]:
        return {
            "enter_high": float(self.value("hysteresis", "enter_high_sol_share", 0.25)),
            "enter_samples": int(self.value("hysteresis", "enter_samples", 2)),
            "leave_high": float(self.value("hysteresis", "leave_high_sol_share", 0.22)),
            "leave_samples": int(self.value("hysteresis", "leave_samples", 2)),
            "critical_1h_share": float(self.value("hysteresis", "critical_1h_share", 0.35)),
        }

    # -- governor bounds ---------------------------------------------------------------
    def planning_max_turns(self) -> int:
        return int(self.value("budget", "planning_max_turns", 6))

    def planning_max_new_tokens(self) -> int:
        return int(self.value("budget", "planning_max_new_tokens", 30_000))

    def l2_max_age_s(self) -> float:
        return float(self.value("l2_queue", "l2_max_age_s", 900))

    def meter_stale_after_s(self) -> float:
        return float(self.value("tokens", "stale_after_s", 7200))


@dataclass
class RefillPolicy:
    """Typed, fail-closed view over ``config/refill_policy.toml`` 鈥?the ONLY
    concurrency authority (P0-8.3).  Any read failure raises
    :class:`PolicyError` instead of returning a divergent default."""

    doc: dict[str, Any] = field(default_factory=dict)
    path: Path | None = None

    @classmethod
    def load(cls, paths: LoopPaths | None = None) -> "RefillPolicy":
        paths = paths or LoopPaths.resolve()
        explicit = os.environ.get("LOOP_REFILL_POLICY")
        policy_path = (Path(explicit).resolve() if explicit
                       else paths.config / "refill_policy.toml")
        return cls(_load_toml(policy_path, "refill policy"), policy_path)

    def _int(self, section: str, key: str) -> int:
        table = self.doc.get(section, {})
        value = table.get(key) if isinstance(table, dict) else None
        if not isinstance(value, int) or isinstance(value, bool):
            raise PolicyError(f"refill policy [{section}].{key} missing/invalid "
                              f"in {self.path} 鈥?fail-closed, no silent default")
        return value

    def target_total(self) -> int:
        return self._int("concurrency", "target_total")

    def dialogue_target(self) -> int:
        return self._int("concurrency", "dialogue_target")

    def v4_target(self) -> int:
        return self._int("concurrency", "v4_target")

    def k3_target(self) -> int:
        return self._int("concurrency", "k3_target")

    def v4_low_water(self) -> int:
        return self._int("concurrency", "v4_low_water")

    def k3_low_water(self) -> int:
        return self._int("concurrency", "k3_low_water")

    def spawn_interval_ms(self) -> int:
        return self._int("spawn_throttle", "spawn_interval_ms")   # 1000

    def reservations_borrowable(self) -> bool:
        table = self.doc.get("concurrency", {})
        value = table.get("reservations_borrowable", True) if isinstance(table, dict) else True
        return bool(value)

    def policy_version(self) -> str:
        table = self.doc.get("meta", {})
        value = table.get("policy_version") if isinstance(table, dict) else None
        return str(value) if value is not None else "unversioned"

#!/usr/bin/env python3
"""Fail-open lifecycle hook for Desktop-native Codex subagents.

This hook maintains a shadow roster and a semantic task-name map.  It never
writes Codex Desktop's ``state_5.sqlite`` and never claims to release a native
runtime slot: the host-only ``close_agent`` tool is represented by an
idempotent close-request record for the orchestrator to consume.
"""
from __future__ import annotations

import argparse
import contextlib
import ctypes
import json
import os
import re
import sys
import time
from pathlib import Path
from typing import Any

if os.name == "nt":
    from ctypes import wintypes


TASK_RE = re.compile(r"(?:^|\n)\s*浠诲姟鍚峔s*[锛?]\s*([^\r\n]{1,160})")
ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,127}\Z")
PENDING_TTL_SECONDS = 600
TERMINAL_MARKERS = {"task_complete", "turn_aborted", "turn_failed", "thread_closed"}
LEGACY_UNRESOLVED_NAMES = {"鏈懡鍚嶅瓙浠诲姟", "鏈槧灏勫瓙浠诲姟"}
NAME_FALLBACK_SOURCE = "agent_id_fallback"
ATOMIC_REPLACE_TIMEOUT_S = 5.0
RETRY_INITIAL_S = 0.005
RETRY_MAX_S = 0.100
LOCK_TIMEOUT_S = 10.0


def project_root() -> Path:
    explicit = os.environ.get("LOOP_ROOT")
    if explicit:
        return Path(explicit).resolve()
    here = Path(__file__).resolve()
    # package/hooks/script.py or target/.codex/hooks/script.py
    return here.parents[2] if here.parent.name == "hooks" and here.parent.parent.name == ".codex" else here.parents[1]


def data_dir() -> Path:
    return Path(os.environ.get("LOOP_DATA_DIR", str(project_root() / "data"))).resolve()


def recompute_refill(root: Path | None = None) -> dict[str, Any] | None:
    """Mechanically recompute the sustained-refill state after a lifecycle event.

    The hook never spawns: it imports the refill controller (harness/) and asks
    it to re-derive refill_required / deficit / model_pool from the native
    roster and the work queue.  Failures are audited and never faked as
    refilled.
    """
    base = (root or project_root()).resolve()
    pkg_harness = Path(__file__).resolve().parents[1] / "harness"
    try:
        for candidate in (pkg_harness, base / "harness"):
            if (candidate / "refill_controller_v2.py").exists():
                sys.path.insert(0, str(candidate))
                break
        from orchestration_common import LoopPaths
        from refill_controller_v2 import RefillControllerV2
        controller = RefillControllerV2(LoopPaths.resolve(base))
        controller.queue_sync_ledger()
        return controller.recompute()
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("refill_recompute_degraded",
                                           error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
        return None


def schedule_refill_actuator(root: Path | None = None, *, source: str) -> dict[str, Any] | None:
    """Trigger the existing epilogue after a terminal lifecycle edge.

    ``recompute_refill`` is the controller (observe + decide), not the
    actuator.  Desktop-native terminal hooks previously stopped after that
    decision, so a real deficit stayed queued until the root agent manually
    dispatched again.  Reuse the headless supervisor's coalesced epilogue
    launcher; it owns the existing epilogue lock and the packet-only refill
    consumer.  This remains fail-open for the lifecycle hook: a failed trigger
    is audited and never reported as a successful refill.
    """
    base = (root or project_root()).resolve()
    try:
        harness = Path(__file__).resolve().parents[1] / "harness"
        if str(harness) not in sys.path:
            sys.path.insert(0, str(harness))
        from refill_consumer_v2 import schedule_run
        result = schedule_run(base, source=source)
        try:
            NativeRoster(data_dir()).audit("refill_actuator_%s" % result.get("status", "unknown"),
                                           source=source, pid=result.get("pid"))
        except BaseException:
            pass
        return result
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("refill_actuator_failed", source=source,
                                           error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
        return None


def refresh_meter(root: Path | None = None) -> dict[str, Any] | None:
    """Refresh the existing rollout-to-meter bridge after lifecycle edges.

    The bridge owns its cross-process lock and policy-configured debounce, so
    invoking it from several Stop events does not multiply full session scans.
    This hook remains fail-open: stale or unavailable session telemetry is
    audited, never presented as a successful refresh.
    """
    base = (root or project_root()).resolve()
    metering = base / "metering"
    try:
        if str(metering) not in sys.path:
            sys.path.insert(0, str(metering))
        from model_token_share_bridge import refresh
        sessions = Path(os.environ.get(
            "CODEX_SESSIONS_DIR",
            str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
        )).resolve()
        return refresh(base, sessions, force=False)
    except BaseException as exc:
        try:
            NativeRoster(data_dir()).audit("meter_refresh_degraded",
                                           error="%s: %s" % (type(exc).__name__, exc))
        except BaseException:
            pass
        return None


@contextlib.contextmanager
def lock(path: Path, *, timeout_s: float = LOCK_TIMEOUT_S):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        handle.seek(0, os.SEEK_END)
        if handle.tell() == 0:
            handle.write(b"\0"); handle.flush()
        handle.seek(0)
        if os.name == "nt":
            import msvcrt
            deadline = time.monotonic() + max(0.0, timeout_s)
            backoff = RETRY_INITIAL_S
            while True:
                try:
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                    break
                except OSError as exc:
                    if time.monotonic() >= deadline:
                        raise RuntimeError(
                            "lifecycle hook lock remained busy for %.3fs: %s"
                            % (timeout_s, exc)) from exc
                    time.sleep(backoff)
                    backoff = min(RETRY_MAX_S, backoff * 2)
        else:
            import fcntl
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def atomic_json(path: Path, value: Any, *,
                replace_timeout_s: float = ATOMIC_REPLACE_TIMEOUT_S) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".%d.tmp" % os.getpid())
    try:
        with tmp.open("w", encoding="utf-8", newline="\n") as handle:
            json.dump(value, handle, ensure_ascii=False, indent=2, sort_keys=True)
            handle.write("\n"); handle.flush(); os.fsync(handle.fileno())
        deadline = time.monotonic() + max(0.0, replace_timeout_s)
        backoff = RETRY_INITIAL_S
        while True:
            try:
                os.replace(tmp, path)
                return
            except PermissionError as exc:
                if time.monotonic() >= deadline:
                    raise RuntimeError(
                        "lifecycle hook atomic replace remained blocked for "
                        "%.3fs: %s" % (replace_timeout_s, exc)) from exc
                time.sleep(backoff)
                backoff = min(RETRY_MAX_S, backoff * 2)
    finally:
        try:
            tmp.unlink()
        except FileNotFoundError:
            pass


def read_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


class NativeRoster:
    def __init__(self, root: Path):
        self.root = root / "lifecycle"
        self.path = self.root / "native_roster.json"
        self.lock_path = self.root / ".native_roster.lock"
        self.close_path = self.root / "close_requests.ndjson"
        self.events_path = self.root / "events.ndjson"
        self.name_map_path = self.root / "name_map.jsonl"
        self.main_events_path = root / "events.ndjson"

    def transact(self, fn):
        with lock(self.lock_path):
            if self.path.exists():
                try:
                    roster = json.loads(self.path.read_text(encoding="utf-8"))
                except (OSError, ValueError) as exc:
                    raise RuntimeError("native roster unreadable; refusing overwrite: %s" % exc) from exc
            else:
                roster = {"schema": "codex-loop-native-roster/v1",
                          "pending": [], "agents": {}}
            result = fn(roster)
            roster["updated_at"] = time.time()
            atomic_json(self.path, roster)
            return result

    def append(self, path: Path, row: dict[str, Any]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        with path.open("a", encoding="utf-8", newline="\n") as handle:
            handle.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")

    def audit(self, event: str, **detail: Any) -> None:
        with lock(self.lock_path.with_name(".native_events.lock")):
            self.append(self.events_path, {"ts": time.time(), "event": event, **detail})

    def main_event_once(self, event: str, agent_id: str, **detail: Any) -> bool:
        with lock(self.lock_path.with_name(".events.lock")):
            try:
                for line in self.main_events_path.read_text(encoding="utf-8").splitlines():
                    try: row = json.loads(line)
                    except ValueError: continue
                    if row.get("event") == event and row.get("agent_id") == agent_id:
                        return False
            except OSError:
                pass
            self.append(self.main_events_path, {"ts": time.time(), "event": event,
                                                "agent_id": agent_id, **detail})
            return True

    def exec_event_once(self, packet_id: str, run_id: str, attempt: int,
                        event: str, **detail: Any) -> bool:
        with lock(self.lock_path.with_name(".events.lock")):
            try:
                for line in self.main_events_path.read_text(encoding="utf-8").splitlines():
                    try: row = json.loads(line)
                    except ValueError: continue
                    if (row.get("packet_id") == packet_id and row.get("run_id") == run_id
                            and row.get("event") == event):
                        return False
            except OSError:
                pass
            self.append(self.main_events_path, {"ts": time.time(), "packet_id": packet_id,
                "run_id": run_id, "attempt": attempt, "event": event, "detail": detail})
            return True

    def queue_close_locked(self, agent: dict[str, Any], reason: str) -> bool:
        if agent.get("close_request_emitted") or agent.get("close_request_consumed"):
            return False
        row = {"ts": time.time(), "agent_id": agent.get("agent_id"),
               "task_name": agent.get("task_name"), "parent_session_id": agent.get("parent_session_id"),
               "reason": reason, "action": "host_close_agent_required"}
        self.append(self.close_path, row)
        agent["close_request_emitted"] = True
        agent["close_request_reason"] = reason
        return True


def payload_task_name(payload: dict[str, Any]) -> str | None:
    tool_input = payload.get("tool_input") or payload.get("input") or payload.get("arguments") or {}
    if isinstance(tool_input, str):
        try: tool_input = json.loads(tool_input)
        except ValueError: tool_input = {"message": tool_input}
    if not isinstance(tool_input, dict):
        tool_input = {}
    explicit = tool_input.get("task_name") or tool_input.get("name")
    if isinstance(explicit, str) and explicit.strip():
        return explicit.strip()[:160]
    # Current multi-agent payloads may normalize the legacy ``message`` into
    # structured ``items``. Walk only in-memory strings and persist only the
    # matched one-line task name, never the raw tool payload.
    queue: list[Any] = [tool_input]
    while queue:
        value = queue.pop()
        if isinstance(value, str):
            match = TASK_RE.search(value)
            if match:
                return match.group(1).strip()[:160]
        elif isinstance(value, dict):
            queue.extend(value.values())
        elif isinstance(value, list):
            queue.extend(value)
    return None


def resolve_identity(payload: dict[str, Any], roster: NativeRoster,
                     context: str) -> tuple[str | None, str | None] | None:
    """Resolve identity fields, auditing and blocking on conflicting duplicates."""
    agent_id = payload.get("agent_id")
    thread_id = payload.get("thread_id")
    session_id = payload.get("session_id")
    parent_thread_id = payload.get("parent_thread_id")
    if agent_id and thread_id and str(agent_id) != str(thread_id):
        roster.audit("identity_conflict", context=context, pair="agent_id/thread_id",
                     agent_id=str(agent_id), thread_id=str(thread_id), action="fail_closed")
        return None
    if session_id and parent_thread_id and str(session_id) != str(parent_thread_id):
        roster.audit("identity_conflict", context=context, pair="session_id/parent_thread_id",
                     session_id=str(session_id), parent_thread_id=str(parent_thread_id),
                     action="fail_closed")
        return None
    return agent_id or thread_id, session_id or parent_thread_id


def recover_arguments_from_parent_rollout(parent_session_id: str | None,
                                          tool_use_id: str | None,
                                          sessions: Path | None = None) -> dict[str, Any] | None:
    """Recover tool arguments when PreToolUse redacts collaboration input.

    Current Desktop builds expose the tool-use id to the hook but can omit the
    spawn message. The parent rollout is the second truth source and already
    contains the function_call before SubagentStart fires.
    """
    if (not parent_session_id or not tool_use_id or
            not ID_RE.fullmatch(str(parent_session_id)) or
            not ID_RE.fullmatch(str(tool_use_id))):
        return None
    root = sessions or Path(os.environ.get("CODEX_SESSIONS_DIR", str(Path.home() / ".codex" / "sessions")))
    if not root.exists():
        return None
    matches = list(root.rglob("rollout-*%s*.jsonl" % parent_session_id))
    for path in sorted(matches, key=lambda p: p.stat().st_mtime, reverse=True):
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try: row = json.loads(line)
                    except ValueError: continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    if payload.get("type") != "function_call" or payload.get("call_id") != tool_use_id:
                        continue
                    arguments = payload.get("arguments") or {}
                    if isinstance(arguments, str):
                        try: arguments = json.loads(arguments)
                        except ValueError: arguments = {"message": arguments}
                    return arguments if isinstance(arguments, dict) else None
        except OSError:
            continue
    return None


def recover_spawn_agent_id(parent_session_id: str | None, tool_use_id: str | None,
                           sessions: Path | None = None) -> str | None:
    """Resolve spawn call_id -> returned agent_id from the parent rollout."""
    if (not parent_session_id or not tool_use_id or
            not ID_RE.fullmatch(str(parent_session_id)) or
            not ID_RE.fullmatch(str(tool_use_id))):
        return None
    root = sessions or Path(os.environ.get("CODEX_SESSIONS_DIR", str(Path.home() / ".codex" / "sessions")))
    if not root.exists():
        return None
    for path in sorted(root.rglob("rollout-*%s*.jsonl" % parent_session_id),
                       key=lambda p: p.stat().st_mtime, reverse=True):
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    if tool_use_id not in line or "function_call_output" not in line:
                        continue
                    try: row = json.loads(line)
                    except ValueError: continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    if payload.get("type") != "function_call_output" or payload.get("call_id") != tool_use_id:
                        continue
                    output = payload.get("output") or {}
                    if isinstance(output, str):
                        try: output = json.loads(output)
                        except ValueError: continue
                    candidate = output.get("agent_id") if isinstance(output, dict) else None
                    return str(candidate) if candidate and ID_RE.fullmatch(str(candidate)) else None
        except OSError:
            continue
    return None


def recover_task_from_parent_rollout(parent_session_id: str | None,
                                     tool_use_id: str | None,
                                     sessions: Path | None = None) -> str | None:
    arguments = recover_arguments_from_parent_rollout(parent_session_id, tool_use_id, sessions)
    return payload_task_name({"tool_input": arguments or {}})


def pre_tool(roster: NativeRoster, payload: dict[str, Any]) -> None:
    tool = str(payload.get("tool_name") or payload.get("tool") or payload.get("name") or "")
    resolved = resolve_identity(payload, roster, "PreToolUse")
    if resolved is None:
        return
    parent = resolved[1]
    tool_use_id = payload.get("tool_use_id")
    if "close_agent" in tool:
        tool_input = payload.get("tool_input") or payload.get("input") or payload.get("arguments") or {}
        if isinstance(tool_input, str):
            try: tool_input = json.loads(tool_input)
            except ValueError: tool_input = {}
        if not isinstance(tool_input, dict): tool_input = {}
        target = tool_input.get("target") or tool_input.get("agent_id") or tool_input.get("id")
        if not target:
            recovered = recover_arguments_from_parent_rollout(parent, tool_use_id)
            if recovered:
                target = recovered.get("target") or recovered.get("agent_id") or recovered.get("id")
        if target:
            def confirm(value):
                item = value.setdefault("agents", {}).get(str(target))
                if not item: return None
                if not item.get("host_close_confirmed_at"):
                    item["host_close_confirmed_at"] = time.time()
                    item["close_request_consumed"] = True
                    item["close_observed_before_request"] = not bool(item.get("close_request_emitted"))
                    item["updated_at"] = time.time()
                return dict(item)
            item = roster.transact(confirm)
            if item:
                roster.audit("host_close_observed", agent_id=str(target),
                             task_name=item.get("task_name"), tool_use_id=tool_use_id)
                recompute_refill()
                schedule_refill_actuator(project_root(), source="desktop_close_observed")
        return
    if "spawn_agent" not in tool:
        return
    task_name = payload_task_name(payload)
    item = {"task_name": task_name, "parent_session_id": parent,
            "tool_use_id": tool_use_id, "created_at": time.time(),
            "status": "pending_start"}
    def mutate(value):
        expired = prune_pending(value, item["created_at"])
        pending = value.setdefault("pending", [])
        key = (item["parent_session_id"], item["tool_use_id"])
        if item["tool_use_id"] and any((x.get("parent_session_id"), x.get("tool_use_id")) == key for x in pending):
            return False, expired
        pending.append(item); return True, expired
    added, expired = roster.transact(mutate)
    if expired:
        roster.audit("pending_expired", count=len(expired),
                     tool_use_ids=[x.get("tool_use_id") for x in expired],
                     trigger="PreToolUse")
    if added:
        roster.audit("spawn_pending", **item)


def prune_pending(value: dict[str, Any], now: float) -> list[dict[str, Any]]:
    """Drop expired or malformed pending starts before matching/de-duplication."""
    active, expired = [], []
    for item in value.setdefault("pending", []):
        if item.get("status") != "pending_start":
            continue
        try:
            created_at = float(item.get("created_at", 0) or 0)
        except (TypeError, ValueError):
            created_at = 0.0
        if now - created_at > PENDING_TTL_SECONDS:
            expired.append(item)
        else:
            active.append(item)
    value["pending"] = active
    return expired


def subagent_start(roster: NativeRoster, payload: dict[str, Any]) -> None:
    resolved = resolve_identity(payload, roster, "SubagentStart")
    if resolved is None:
        return
    agent_id, parent = resolved
    if not agent_id:
        roster.audit("subagent_start_degraded", reason="missing_agent_id")
        return
    now = time.time()
    def mutate(value):
        agents = value.setdefault("agents", {})
        if agent_id in agents:
            return agents[agent_id], []
        expired = prune_pending(value, now)
        pending = value.setdefault("pending", [])
        candidates = [x for x in pending
                      if x.get("status") == "pending_start" and
                      (not parent or not x.get("parent_session_id") or x.get("parent_session_id") == parent)]
        exact = [x for x in candidates
                 if recover_spawn_agent_id(parent, x.get("tool_use_id")) == str(agent_id)]
        chosen = min(exact, key=lambda x: x.get("created_at", 0)) if exact else (
                 candidates[0] if len(candidates) == 1 else None)
        if chosen:
            pending.remove(chosen)
            if chosen in exact:
                chosen["mapping_source"] = "parent_rollout_function_call_output"
        task_name = chosen.get("task_name") if chosen else None
        if task_name in LEGACY_UNRESOLVED_NAMES:
            task_name = None
        if chosen and task_name is None:
            recovered = recover_task_from_parent_rollout(parent, chosen.get("tool_use_id"))
            if recovered:
                task_name = recovered
                chosen["task_name"] = recovered
                chosen["mapping_source"] = "parent_rollout_function_call"
        name_degraded = False
        name_source = None
        if not task_name:
            task_name = str(agent_id)
            name_degraded = True
            name_source = NAME_FALLBACK_SOURCE
        item = {"agent_id": agent_id, "task_name": task_name,
                "name_degraded": name_degraded, "name_source": name_source,
                "parent_session_id": parent, "agent_role": payload.get("agent_type") or payload.get("agent_role"),
                "model": payload.get("model") or payload.get("agent_model"),
                "nickname": payload.get("agent_nickname"), "status": "running",
                "started_at": now, "updated_at": now,
                "mapping_confidence": ("tool_use+rollout" if chosen and chosen.get("mapping_source") else
                                       "tool_use" if chosen and chosen.get("tool_use_id") else
                                       "parent_fifo" if chosen else "unmapped")}
        agents[agent_id] = item
        self_row = {**item, "source": "SubagentStart"}
        roster.append(roster.name_map_path, self_row)
        return item, expired
    item, expired = roster.transact(mutate)
    if expired:
        roster.audit("pending_expired", count=len(expired),
                     tool_use_ids=[x.get("tool_use_id") for x in expired])
    roster.main_event_once("SubagentStart", str(agent_id),
                           agent_role=item.get("agent_role"), model=item.get("model"),
                           session_id=item.get("parent_session_id"), task_name=item.get("task_name"))
    roster.audit("subagent_started", **item)


def subagent_stop(roster: NativeRoster, payload: dict[str, Any]) -> None:
